{"read_file": """"miner_3 one-idea validation: drawdown-recovery efficiency."""
import glob,json
import numpy as np,pandas as pd
ASSETS=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
F={}; FW={}; L={'miner_3_risk_adjusted_trend_20d':{},'miner_1_ravmom_20obs':{},'miner_1_volnorm_reversal_5obs':{}}
for a in ASSETS:
 d=pd.read_csv(f'../persistent/stock_data/{a}.csv',parse_dates=['date']).set_index('date').sort_index(); p=d.close.astype(float); r=p.pct_change()
 # A positive score requires a positive 5-observation rebound, scaled by distance still remaining to the preceding 60-observation high.
 dd=p/p.rolling(60,min_periods=45).max()-1
 F[a]=(p/p.shift(5)-1)/(0.02-dd.clip(upper=0))
 FW[a]={h:p.shift(-h)/p-1 for h in (1,5,10,20)}
 L['miner_3_risk_adjusted_trend_20d'][a]=(p/p.shift(20)-1)/r.rolling(20,min_periods=15).std()
 L['miner_1_ravmom_20obs'][a]=L['miner_3_risk_adjusted_trend_20d'][a]
 L['miner_1_volnorm_reversal_5obs'][a]=-(p/p.shift(5)-1)/r.rolling(5,min_periods=4).std()
f=pd.DataFrame(F).sort_index()
print('FACTOR: drawdown_recovery_efficiency_60_5 = return_5 / (0.02 - min(close/rolling_max_60-1,0)); high is an efficient rebound from a remaining drawdown')
print('history',f.index.min().date(),f.index.max().date(),'instruments',len(ASSETS))
def iccalc(h):
 fw=pd.DataFrame({a:FW[a][h] for a in ASSETS}); x=[]; cov=[]
 for dt in f.index:
  z=pd.DataFrame({'s':f.loc[dt],'r':fw.loc[dt]}).dropna()
  if len(z)>=8: x.append((dt,z.s.corr(z.r,method='spearman')));cov.append(len(z)/15)
 return pd.Series(dict(x)),np.mean(cov)
for h in (1,5,10,20):
 x,c=iccalc(h); print(f'h={h} dates={len(x)} meanIC={x.mean():.6f} ICIR={x.mean()/x.std(ddof=1):.6f} hit={(x>0).mean():.4f} IC_se={x.std(ddof=1)/np.sqrt(len(x)):.6f} coverage={c:.4f}')
 for nm,m in [('2020',x.index<'2021-01-01'),('2021_22',(x.index>='2021-01-01')&(x.index<'2023-01-01')),('2023_24',(x.index>='2023-01-01')&(x.index<'2025-01-01')),('2025_26',x.index>='2025-01-01')]:
  z=x[m]; print(f'  {nm}: n={len(z)} IC={z.mean():.6f} ICIR={z.mean()/z.std(ddof=1):.6f} hit={(z>0).mean():.4f}')
r=f.rank(axis=1,pct=True); turn=[]
for i in range(1,len(r)):
 z=pd.concat([r.iloc[i-1],r.iloc[i]],axis=1).dropna()
 if len(z)>=8:turn.append(1-z.iloc[:,0].corr(z.iloc[:,1],method='spearman'))
print(f'turnover_rank_change={np.mean(turn):.6f}; valid_signal_cells={f.notna().sum().sum()}/{f.size} ({f.notna().mean().mean():.4f})')
mx=0; evidence={}
for name,vals in L.items():
 z=pd.concat([f.stack().rename('a'),pd.DataFrame(vals).stack().rename('b')],axis=1).dropna(); rho=z.a.corr(z.b,method='spearman'); evidence[name]=(rho,len(z));mx=max(mx,abs(rho));print(f'library {name}: rho={rho:.6f} cells={len(z)}')
print(f'LIBRARY records={len(glob.glob("factors/*.json"))} max_abs_library_correlation={mx:.6f}')
"}

