ranks=f.rank(axis=1,pct=True); turn=(ranks-ranks.shift(10)).abs().stack().mean()
print('FACTOR miner_2_realized_volatility_20obs');print('VALIDATION_DATE',END.date(),'signal_start',f.index.min().date(),'signal_dates',len(f),'universe',len(A),'coverage',float(f.notna().sum().sum()/f.size),'mean_names_per_signal_date',float(f.notna().sum(axis=1).mean()),'turnover_10d_rank',float(turn));print('DECAY',json.dumps({str(h):m for h,(s,m) in R.items()},sort_keys=True))
