print('FACTOR low_spx_beta_20obs');print('PERIOD',f.index.min().date(),E.date(),'panel_dates',len(f),'coverage',float(f.notna().mean().mean()),'mean_names',float(f.notna().sum(axis=1).mean()),'mean_rank_turnover_1d',float(np.mean(t)))
