   q=ic[mask]; print('REGIME',label,'dates',len(q),'ic',round(q.mean(),6),'icir',round(q.mean()/q.std(ddof=1),6),'hit',round((q>0).mean(),4))
ranks=f.rank(axis=1,pct=True); turnover=(ranks-ranks.shift(10)).abs().stack().mean(); coverage=f.notna().sum().sum()/f.size
libs={'miner_3_risk_adjusted_trend_20d':pd.DataFrame(trend),'miner_1_ravmom_20obs':pd.DataFrame(trend),'miner_1_volnorm_reversal_5obs':pd.DataFrame(reversal),'miner_3_relative_volume_participation_20d':pd.DataFrame(relvol)}
corr={}; ev={}
for name,panel in libs.items():
