print('FACTOR realized_volatility_20obs; period',f.index.min().date(),END.date(),'assets',len(ASSETS))
print('coverage',round(coverage,4),'signal_cells',int(f.notna().sum().sum()),'of',f.size,'turnover_10d_rank',round(turnover,6))
print('LIBRARY_CORRELATIONS',json.dumps(corr,sort_keys=True),'common_cells',json.dumps(ev,sort_keys=True),'max_abs',round(max(map(abs,corr.values())),6))
print('DECAY',json.dumps({str(h):{'ic':round(float(x.mean()),6),'icir':round(float(x.mean()/x.std(ddof=1)),6),'dates':len(x)} for h,(x,n) in results.items()}))
