print('MAX_ABS_LIBRARY_CORRELATION',round(mx,6),'COMPLETE',complete,'LIBRARY_COUNT',len(lib));print('DECAY',json.dumps({str(h):{k:float(v) for k,v in q.items()} for h,q in metrics.items()}))

