for w,n in [(20,8),(120,8)]:
 z=np.full(R.shape,np.nan)
 for t in range(w-1,len(r)):
  q=M[t-w+1:t+1]<0
  for k in range(15):
   x=R[t-w+1:t+1,k][q]; y=M[t-w+1:t+1][q]
